mapper.select:
SELECT  FROM t_authentication_challenge
WHERE realm='CUSTOMER' AND account_id=#{accountId} AND purpose=#{purpose}
ORDER BY create_time DESC, challenge_id DESC LIMIT 1

SELECT  FROM t_authentication_challenge
WHERE realm='CUSTOMER' AND purpose IN ('SIGN_UP_EMAIL','PASSWORD_RESET') AND challenge_no=#{challengeNo}
  AND account_id IS NOT NULL AND tenant_invitation_id IS NULL

SELECT  FROM t_authentication_challenge
WHERE realm='CUSTOMER' AND purpose IN ('SIGN_UP_EMAIL','PASSWORD_RESET') AND challenge_id=#{id}
  AND account_id IS NOT NULL AND tenant_invitation_id IS NULL FOR UPDATE

mapper.update:
UPDATE t_user_account SET status='ACTIVE', email_verified_time=#{now}, version=version+1, update_time=#{now}
WHERE account_id=#{id} AND realm='CUSTOMER' AND status='PENDING_VERIFICATION'
  AND email_verified_time IS NULL AND email_vault_token=#{token} AND version=#{version}

UPDATE t_user_account SET credential_version=credential_version+1, auth_epoch=auth_epoch+1,
    consecutive_password_failures=0, locked_until=NULL, last_password_failure_time=NULL,
    version=version+1, update_time=#{now}
WHERE account_id=#{id} AND realm='CUSTOMER' AND status='ACTIVE' AND email_verified_time IS NOT NULL
  AND version=#{version}

UPDATE t_password_credential SET password_verifier_phc=#{verifier}, algorithm_code='ARGON2ID',
    algorithm_version=19, memory_kib=19456, iterations=2, parallelism=1,
    credential_version=credential_version+1, force_change_flag=0,
    password_changed_time=#{now}, version=version+1, update_time=#{now}
WHERE account_id=#{accountId} AND status='ACTIVE' AND credential_version=#{credentialVersion}

UPDATE t_auth_session SET status='REVOKED', revocation_reason='PASSWORD_RESET', revoked_time=#{now},
    version=version+1, update_time=#{now}
WHERE account_id=#{accountId} AND realm='CUSTOMER' AND status='ACTIVE'

UPDATE t_refresh_token_generation r JOIN t_auth_session s ON s.session_id=r.session_id
SET r.status='REVOKED', r.active_slot=NULL, r.version=r.version+1, r.update_time=#{now}
WHERE s.account_id=#{accountId} AND s.realm='CUSTOMER' AND r.status='ISSUED'

UPDATE t_user_account SET credential_version=credential_version+1, auth_epoch=auth_epoch+1,
    version=version+1, update_time=#{now}
WHERE account_id=#{id} AND realm='CUSTOMER' AND status='PENDING_VERIFICATION'
  AND email_verified_time IS NULL AND version=#{version}
